DECLARE @B bigint=(SELECT BatchId FROM ssis_flow.Context),@Previous bigint=(SELECT PreviousVersion FROM ssis_flow.Context),@Next bigint=(SELECT NextVersion FROM ssis_flow.Context);
IF @Previous IS NULL BEGIN
INSERT etl_raw.[SpecialOffer]([SpecialOfferID],[Description],[DiscountPct],[Type],[Category],[StartDate],[EndDate],[MinQty],[MaxQty],[rowguid],[ModifiedDate],LoadBatchID) SELECT S.[SpecialOfferID],S.[Description],S.[DiscountPct],S.[Type],S.[Category],S.[StartDate],S.[EndDate],S.[MinQty],S.[MaxQty],S.[rowguid],S.[ModifiedDate],@B FROM ssis_flow.Delta_SpecialOffer S;
INSERT stg.[SpecialOffer]([SpecialOfferID],[Description],[DiscountPct],[Type],[Category],[StartDate],[EndDate],[MinQty],[MaxQty],[rowguid],[ModifiedDate],LoadBatchID) SELECT [SpecialOfferID],[Description],[DiscountPct],[Type],[Category],[StartDate],[EndDate],[MinQty],[MaxQty],[rowguid],[ModifiedDate],@B FROM etl_raw.[SpecialOffer];
INSERT etl_v2.SourceChange SELECT @B,N'Sales.SpecialOffer','I',@Next,(SELECT R.[SpecialOfferID] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER),NULL FROM etl_raw.[SpecialOffer] R;
END ELSE BEGIN
SELECT [SpecialOfferID],CONVERT(char(1),FlowOperation) SYS_CHANGE_OPERATION,FlowVersion SYS_CHANGE_VERSION INTO #CT_SpecialOffer FROM ssis_flow.Delta_SpecialOffer;
INSERT etl_v2.SourceChange SELECT @B,N'Sales.SpecialOffer',C.SYS_CHANGE_OPERATION,C.SYS_CHANGE_VERSION,(SELECT C.[SpecialOfferID] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER),(SELECT R.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES) FROM #CT_SpecialOffer C LEFT JOIN etl_raw.[SpecialOffer] R ON R.[SpecialOfferID]=C.[SpecialOfferID];
DELETE R FROM etl_raw.[SpecialOffer] R JOIN #CT_SpecialOffer C ON R.[SpecialOfferID]=C.[SpecialOfferID] WHERE C.SYS_CHANGE_OPERATION='D';
UPDATE R SET R.[Description]=S.[Description],R.[DiscountPct]=S.[DiscountPct],R.[Type]=S.[Type],R.[Category]=S.[Category],R.[StartDate]=S.[StartDate],R.[EndDate]=S.[EndDate],R.[MinQty]=S.[MinQty],R.[MaxQty]=S.[MaxQty],R.[rowguid]=S.[rowguid],R.[ModifiedDate]=S.[ModifiedDate],R.LoadBatchID=@B FROM etl_raw.[SpecialOffer] R JOIN #CT_SpecialOffer C ON R.[SpecialOfferID]=C.[SpecialOfferID] JOIN ssis_flow.Delta_SpecialOffer S ON S.[SpecialOfferID]=C.[SpecialOfferID] WHERE C.SYS_CHANGE_OPERATION<>'D';
INSERT etl_raw.[SpecialOffer]([SpecialOfferID],[Description],[DiscountPct],[Type],[Category],[StartDate],[EndDate],[MinQty],[MaxQty],[rowguid],[ModifiedDate],LoadBatchID) SELECT S.[SpecialOfferID],S.[Description],S.[DiscountPct],S.[Type],S.[Category],S.[StartDate],S.[EndDate],S.[MinQty],S.[MaxQty],S.[rowguid],S.[ModifiedDate],@B FROM #CT_SpecialOffer C JOIN ssis_flow.Delta_SpecialOffer S ON S.[SpecialOfferID]=C.[SpecialOfferID] WHERE C.SYS_CHANGE_OPERATION<>'D' AND NOT EXISTS(SELECT 1 FROM etl_raw.[SpecialOffer] R WHERE R.[SpecialOfferID]=S.[SpecialOfferID]);
INSERT stg.[SpecialOffer]([SpecialOfferID],[Description],[DiscountPct],[Type],[Category],[StartDate],[EndDate],[MinQty],[MaxQty],[rowguid],[ModifiedDate],LoadBatchID) SELECT R.[SpecialOfferID],R.[Description],R.[DiscountPct],R.[Type],R.[Category],R.[StartDate],R.[EndDate],R.[MinQty],R.[MaxQty],R.[rowguid],R.[ModifiedDate],@B FROM etl_raw.[SpecialOffer] R JOIN #CT_SpecialOffer C ON R.[SpecialOfferID]=C.[SpecialOfferID] WHERE C.SYS_CHANGE_OPERATION<>'D';
END;